O3 = zeros(3, 3)

CONDITION_LABELS = [
    "H_1: Let G be generated by an element a.",
    "H_2: Let the order of G be a finite integer n.",
    "H_3: Let k be an integer.",
    "¬Q: The subgroup generated by a^k is NOT equal to the subgroup generated by a^gcd(k,n)."
]

N_HYP = 3
NEG_Q_INDEX = 3

def power(x, p):
    """Safely compute x^p for group/semigroup elements."""
    try:
        return x ** p
    except Exception:
        pass
    if p == 0:
        raise ValueError("Cannot compute 0th power without identity")
    if p < 0:
        raise ValueError("Cannot compute negative power without inverse")
    res = x
    for _ in range(p - 1):
        try:
            res = res * x
        except Exception:
            res = res + x
    return res

def generated_subgroup(x, max_size=10000):
    """Compute the subgroup (or subsemigroup) generated by x."""
    subgroup = set()
    current = x
    for _ in range(max_size):
        if current in subgroup:
            break
        subgroup.add(current)
        try:
            current = current * x
        except Exception:
            current = current + x
    return subgroup

def conditions(witness) -> list[bool]:
    try:
        G, a, n, k = witness
    except Exception:
        return [False, False, False, False]
        
    # Safely extract elements of G
    try:
        G_set = set()
        count = 0
        for x in G:
            G_set.add(x)
            count += 1
            if count > 10000:
                break
    except Exception:
        G_set = set()
        
    # H_1: G is generated by an element a
    try:
        gen_a = generated_subgroup(a)
        h1 = (gen_a == G_set) and (len(G_set) > 0)
    except Exception:
        h1 = False
        
    # H_2: the order of G is a finite integer n
    try:
        if hasattr(G, 'order') and callable(G.order):
            h2 = (G.order() == n)
        else:
            h2 = (len(G_set) == n)
    except Exception:
        h2 = False
        
    # H_3: k is an integer
    try:
        h3 = isinstance(k, int) and not isinstance(k, bool)
    except Exception:
        h3 = False
        
    # ¬Q: The subgroup generated by a^k is NOT equal to the subgroup generated by a^gcd(k,n)
    try:
        ak = power(a, k)
        g = math.gcd(k, n)
        ag = power(a, g)
        
        sub_ak = generated_subgroup(ak)
        sub_ag = generated_subgroup(ag)
        
        neg_q = (sub_ak != sub_ag)
    except Exception:
        neg_q = False
        
    return [h1, h2, h3, neg_q]